CREATE TABLE vote_heads (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE invoices (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), term_id text NOT NULL, vote_head_id text NOT NULL REFERENCES vote_heads(id), amount_cents bigint NOT NULL CHECK (amount_cents > 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fee_ledger_entries (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), reference_id text NOT NULL, description text NOT NULL, debit_cents bigint NOT NULL DEFAULT 0 CHECK (debit_cents >= 0), credit_cents bigint NOT NULL DEFAULT 0 CHECK (credit_cents >= 0), reversal_of text REFERENCES fee_ledger_entries(id), created_at timestamptz NOT NULL DEFAULT now(), CHECK (debit_cents > 0 OR credit_cents > 0), CHECK (NOT (debit_cents > 0 AND credit_cents > 0)));
CREATE OR REPLACE FUNCTION prevent_ledger_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'fee ledger entries are append-only; use a reversal'; END $$;
CREATE TRIGGER fee_ledger_entries_immutable BEFORE UPDATE OR DELETE ON fee_ledger_entries FOR EACH ROW EXECUTE FUNCTION prevent_ledger_mutation();
CREATE TABLE fee_result_waivers (id text PRIMARY KEY, school_id text NOT NULL REFERENCES tenants(id), student_id text NOT NULL REFERENCES students(id), amount_cents bigint NOT NULL CHECK (amount_cents >= 0), reason text NOT NULL, approved_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
